"""P2-qのR5宣言。構造への写像の可否の診断（P2-p）の表せる行に、Observation の status・code と Provenance の宣言を適用する合成の拡張の18義務（共通4＋R5の3＋QR-1〜11）。"""
import hashlib


def observation_manifest(root):
    tests = 'tests/p2/test_observation.py::ObservationTests.'
    mutants = 'test_selected_mutants_are_detected_by_reference'
    first = lambda name: name if isinstance(name, list) else [name]
    property_ref = 'fiction:measurement:property:A@1'
    rows = [
        ('K-ID', '自己・P2-pの版と実体を固定し、旧profileや他拡張の結果を代用しない', 'test_static_validation_pins_limits_and_native_refusals',
         'N02-profile_spec_sha256', ['status'], 'unsupported_profile', False, 'refusal'),
        ('K-STOP', 'P2-pの停止（表せない・評価不能・不足の行）をそのまま通し、宣言の適用は表せる行だけに行う', 'test_rows_not_evaluated_or_not_declared_pass_through_the_grounding_rows',
         'Q12', ['results', 0, 'reason_codes'], ['not_decimal_representable'], False, 'boundary'),
        ('K-INV', '推測で補った情報を作らず、入力を変更せず、臨床の主張を追加しない', 'test_declared_mappings_are_used_but_never_chosen',
         'Q01', ['inferred_information'], [], False, 'non_conversion'),
        ('K-RES', '共通予算に従い、未完了の行に値を返さず、資源停止で認定しない', 'test_budget_sweep_keeps_finished_rows_and_has_no_partial_values',
         'B01-41', ['certificate', 'status'], 'not_certified', False, 'boundary'),
        ('R5-1', '使った宣言（status・code・確認者の型）を仮定として示す', 'test_hand_expectations_api_cli_manifest_and_obligations',
         'Q01', ['results', 0, 'flows', 'added'],
         ['assumption:code_mapping_declared', 'assumption:reviewer_type_declared', 'assumption:status_mapping:original:final'], False, 'boundary'),
        ('R5-2', '保存・医学的な意味の認定を出さない', 'test_declared_mappings_are_used_but_never_chosen',
         'Q01', ['certificate', 'status'], 'not_certified', False, 'non_conversion'),
        ('R5-3', '構造への適合・臨床の傾向・基底への変換を主張しない', 'test_declared_mappings_are_used_but_never_chosen',
         'Q01', ['converted_to_base'], False, False, 'non_conversion'),
        ('QR-1', '自己・P2-pのprofileと仕様hash、構造の事実の出典のハッシュを固定し、呼び出し側が事実を変えられない',
         ['test_static_validation_pins_limits_and_native_refusals', 'test_structure_facts_are_bound_to_their_sources'],
         'N02-grounding_profile_spec_sha256', ['reason_codes'], ['grounding_profile_mismatch'], False, 'refusal'),
        ('QR-2', '確認を作らず、参照時点で見える人の確認だけをProvenanceに運ぶ', 'test_confirmations_origins_and_visibility',
         'Q19', ['results', 0, 'selection', 'review_refs'], ['RA'], True, 'boundary'),
        ('QR-3', 'P2-pの選択をそのまま使い、再選択しない', 'test_rows_not_evaluated_or_not_declared_pass_through_the_grounding_rows',
         'Q06', ['results', 0, 'selection', 'record_ref'], 'B', True, 'boundary'),
        ('QR-4', '停止の順序（P2-pの停止→静的検査→code→status→provenance）と状態の優先を守る', 'test_rows_not_evaluated_or_not_declared_pass_through_the_grounding_rows',
         'Q13', ['results', 0, 'observation', 'state'], 'not_declared', True, 'boundary'),
        ('QR-5', '全体の料金・子の予約の使い切り・原子性・最後の確定を照合する',
         ['test_full_cost_funded_once_and_the_child_uses_its_reservation', 'test_child_failure_and_mismatch_are_atomic_and_refused'],
         'Q01', ['steps_used'], 42, True, 'boundary'),
        ('QR-6', '宣言のない写像を推測で補わず、宣言する人への依頼にする', ['test_declared_mappings_are_used_but_never_chosen', mutants],
         'Q08', ['results', 0, 'requests'], [{'element': 'status', 'action': 'declare_correction_status', 'record_ref': 'B', 'property_ref': None}], True, 'non_conversion'),
        ('QR-7', 'statusの許容集合（原本はfinal、訂正はamended・corrected）と、選ばれた記録による選択', ['test_declaration_enumeration_against_the_oracle', mutants],
         'N08-original-amended', ['reason_codes'], ['unsupported_status_mapping'], False, 'refusal'),
        ('QR-8', 'codeの写像（宣言の表）と、表にない性質の依頼', ['test_declaration_enumeration_against_the_oracle', 'test_declared_mappings_are_used_but_never_chosen', mutants],
         'Q09', ['results', 0, 'requests'], [{'element': 'code', 'action': 'declare_code_mapping', 'record_ref': 'A', 'property_ref': property_ref}], True, 'boundary'),
        ('QR-9', 'Provenanceの項目の規則（確認ごと、時刻順、AI由来だけ生成を先頭に、観察者が不明な生成は出さない）', ['test_confirmations_origins_and_visibility', mutants],
         'Q05', ['results', 0, 'observation', 'provenance', 0, 'activity'], 'creation', True, 'boundary'),
        ('QR-10', '流れの規則（運んだものを保持に移し、使った宣言を仮定に足す）', ['test_declaration_enumeration_against_the_oracle', mutants],
         'Q16', ['results', 0, 'flows', 'lost'],
         ['context_state_distinction:method', 'origin_kind', 'quantity_kind', 'review:identity', 'revision_history', 'validity'], True, 'boundary'),
        ('QR-11', '構造の事実が出典に結ばれ、許容外の確認者の型を拒否する', 'test_structure_facts_are_bound_to_their_sources',
         'N11-reviewer-device', ['reason_codes'], ['unsupported_reviewer_type'], False, 'refusal'),
        ('QR-12', '記録の観察者から生成のProvenanceを出す。人の観察者の型は宣言を使い、推測せず依頼にする', 'test_observer_creation_provenance_and_types_are_never_guessed',
         'Q21', ['results', 0, 'requests'], [{'element': 'provenance', 'action': 'declare_observer_type', 'record_ref': 'A', 'property_ref': None}], True, 'non_conversion')]
    obligations = [{'id': ident, 'statement': text, 'evidence': 'finite_check' if finite else 'checked_native_template',
                    'checks': [tests+name for name in first(test)],
                    'guards': [{'example': 'examples/p2-observation/'+example.lower()+'.json', 'path': path, 'equals': value, 'kind': kind}]}
                   for ident, text, test, example, path, value, finite, kind in rows]
    return {'schema_version': 'p2-extension-manifest-draft-2', 'id': 'p2-observation-projection', 'version': 'draft-2',
            'title': '構造への写像の可否の診断の表せる行に、Observation の status・code と Provenance の宣言を適用し、足りない宣言を依頼にする',
            'status': {'review_state': 'author_draft', 'independent_review': False}, 'class': 'R5',
            'spec': {'path': 'src/med_dsl/observation_projection_spec.json', 'sha256': hashlib.sha256((root/'src/med_dsl/observation_projection_spec.json').read_bytes()).hexdigest()},
            'contract_doc': 'docs/research/70-p2-q-design.md', 'implementation': {'modules': ['src/med_dsl/observation_projection.py']},
            'pins': [{'path': 'src/med_dsl/host.py', 'role': 'dispatcher'}, {'path': 'docs/research/71-p2-q-cases.md', 'role': 'hand_specified_expectations'},
                     {'path': 'src/med_dsl/structure_grounding_spec.json', 'role': 'structure_grounding_native_spec'},
                     {'path': 'src/med_dsl/clinical_library_spec.json', 'role': 'clinical_library_native_spec'},
                     {'path': 'src/med_dsl/temporal_measurement_spec.json', 'role': 'temporal_measurement_native_spec'},
                     {'path': 'src/med_dsl/quantity_spec.json', 'role': 'quantity_native_spec'}],
            'embedded_in': ['src/med_dsl/observation_projection_spec.json', 'src/med_dsl/structure_grounding.py', 'src/med_dsl/structure_grounding_spec.json', 'src/med_dsl/clinical_library.py',
                            'examples/p2-observation/*.json', 'examples/p2-grounding/*.json', 'examples/p2-library/*.json'],
            'depends_on': [{'id': 'p0-positive', 'version': 'draft-2'}, {'id': 'p2-structure-grounding', 'version': 'draft-2'}],
            'owns': {'operations': ['run_observation_projection'], 'schema_versions': ['p2-observation-request-draft-1', 'p2-observation-result-draft-1'],
                     'profiles': ['p2-observation-projection-draft-1'], 'answer_kinds': ['observation_projection'], 'predicates': [],
                     'capabilities': ['p2-observation-projection-draft-1']},
            'scope': {'base_requests': '旧要求とP2-p・P2-o・P2-i・P2-fを変えず、P2-pを固定版で一度だけ実行し、表せる行にだけ宣言を適用する',
                      'fragment': 'Observation の status（original→final、correction→amended／corrected）と code（宣言の表）と、確認ごとの Provenance（確認者の型は宣言）、AI由来の生成の Provenance。revision の entity、activity の符号、署名、他の status の値、符号の系の検証は範囲外。FHIRへの適合は主張しない'},
            'obligations': obligations,
            'stops': {'unknown_capability': 'P2-pの行（表せない・評価不能・不足）は、そのまま通し not_evaluated と明示する',
                      'unsupported': 'unsupported_profile。許容外の status の写像・確認者の型を補完しない',
                      'resource': 'resource_limit。未完了の八欄は全てnull、完成料金前は認定なし、子の部分結果は使わない',
                      'invalid_input': '子の要求（P2-p・P2-oの検査）と宣言の形を予算前に検査'},
            'composition': {'shares_names_with': [], 'reads_extensions': ['p2-structure-grounding'], 'order_dependent': False},
            'evaluation': {'examples': ['examples/p2-observation/*.json'], 'tests': ['tests/p2/test_observation.py'], 'budget_sweep': True, 'oracle': 'tests/p2/observation_oracle.py'}}
